import { css } from "styled-system/css";

/**
 * Numeric typography for the two roles this app renders (#408).
 *
 * **`money`** — a displayed currency amount. Space Mono, because the amounts
 * are the subject of their block: dashboard net and balance, the ledger totals,
 * a transaction row, a van price. The face ships as two `unicode-range`d woff2
 * subsets declared in [`app/app.css`](app/app.css) and generated by
 * `bun run fonts:subset-money`, so it never renders letters — keep prose out of
 * a `money` element and style the suffix separately.
 *
 * **`tabularNums`** — any other numeral that sits in a column or updates in
 * place: counts, percentages, averages, dates, range labels. Inter carries this
 * with zero extra bytes; do not reach for a second family to align statistics,
 * because alignment is the only thing they need.
 *
 * Figures are `lining-nums tabular-nums` on purpose. Lining keeps the digits on
 * the cap line beside a label; tabular keeps columns stable, and keeps them
 * stable through the optimistic re-render of a balance.
 *
 * Weight stays local to the call site and must be `normal` or `bold` — the only
 * two weights the money faces ship. Asking for `semibold` or `extrabold` renders
 * as 700 while the CSS reads as something else.
 *
 * @see https://github.com/fringe4life/van-life/issues/408 — the rule and the
 * money-versus-statistics decision
 */
const money = css({
  fontFamily: "mono",
  fontVariantNumeric: "lining-nums tabular-nums",
});

const tabularNums = css({
  fontVariantNumeric: "tabular-nums",
});

export { money, tabularNums };
